/* Shared Steam identity across ACC and ACE; existing Supabase session and profile API. */
(() => {
 const game=document.body.dataset.game, lang=document.documentElement.lang, profile=document.querySelector('#account-app');
 if(!game)return;
 const base=document.querySelector('meta[name="atx-base"]')?.content||'/atxracing/';
 // Keep the selected event, public driver or category when changing language.
 const page=document.body.dataset.page, current=new URLSearchParams(location.search);
 const preserved=new URLSearchParams();
 if(page==='event'&&/^[a-z0-9]+(?:-[a-z0-9]+)*$/.test(current.get('slug')||''))preserved.set('slug',current.get('slug'));
 if(page==='profile'&&/^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(current.get('driver')||''))preserved.set('driver',current.get('driver'));
 if(['calendar','ranking'].includes(page)&&['WGT','DR','BA'].includes(current.get('type')?.toUpperCase()))preserved.set('type',current.get('type').toUpperCase());
 if(preserved.size)document.querySelectorAll('.header-languages a').forEach(a=>{a.href+='?'+preserved.toString()});
 const endpoint='https://twjpjzalyvbsdpbzhqln.supabase.co/functions/v1/';
 const storageKey='atx-racing-session';
 const ui={
 fr:{connect:'Connexion Steam',my:'Mon profil',guest:'Votre identité pilote commence ici.',guestLead:'Connectez votre compte Steam pour retrouver vos résultats et personnaliser votre profil ATXRACING.',login:'Se connecter avec Steam',welcome:'Bienvenue',help:'Premiers pas',helpText:'Complétez votre profil à votre rythme. Ces étapes rendent votre carte pilote plus utile aux autres membres.',identity:'Identité',photo:'Photo',team:'Équipe',bio:'Présentation',links:'Liens',done:'profil complété',edit:'Personnaliser mon profil',displayName:'Pseudo pilote',country:'Pays (code de 2 lettres)',number:'Numéro de voiture',bioFr:'Présentation en français',bioEn:'Présentation en anglais',twitch:'Twitch',tiktok:'TikTok',youtube:'YouTube',website:'Site web',save:'Enregistrer mon profil',saving:'Enregistrement…',saved:'Profil enregistré.',error:'Impossible d’enregistrer le profil. Vérifiez les informations.',avatar:'Choisir une photo (JPG, PNG ou WebP, 2 Mo maximum)',upload:'Mettre à jour la photo',uploading:'Envoi de la photo…',logout:'Se déconnecter',results:'Historique des courses',empty:'Aucun résultat publié pour ce pilote.',public:'Voir ma carte publique',rank:'Performance',safe:'SAFE',races:'Courses',wins:'Victoires',podiums:'Podiums',points:'Points',best:'Meilleurs tours',noTime:'Aucun tour publié.',first:'Votre première connexion est réussie. Complétez les étapes ci-dessous pour présenter votre parcours.',authError:'Connexion Steam non terminée. Veuillez réessayer.'},
 en:{connect:'Sign in with Steam',my:'My profile',guest:'Your driver identity starts here.',guestLead:'Connect your Steam account to see your results and customise your ATXRACING profile.',login:'Sign in with Steam',welcome:'Welcome',help:'Getting started',helpText:'Complete your profile at your own pace. These steps help other drivers discover you.',identity:'Identity',photo:'Photo',team:'Team',bio:'About you',links:'Links',done:'profile complete',edit:'Customise my profile',displayName:'Driver name',country:'Country (2-letter code)',number:'Car number',bioFr:'About you in French',bioEn:'About you in English',twitch:'Twitch',tiktok:'TikTok',youtube:'YouTube',website:'Website',save:'Save profile',saving:'Saving…',saved:'Profile saved.',error:'Could not save the profile. Check the details.',avatar:'Choose a photo (JPG, PNG or WebP, up to 2 MB)',upload:'Update photo',uploading:'Uploading photo…',logout:'Sign out',results:'Race history',empty:'No published results for this driver.',public:'View my public card',rank:'Performance',safe:'SAFE',races:'Races',wins:'Wins',podiums:'Podiums',points:'Points',best:'Best laps',noTime:'No published lap yet.',first:'Your first sign-in is complete. Follow these steps to present your racing history.',authError:'Steam sign-in did not finish. Please try again.'},
 de:{connect:'Mit Steam anmelden',my:'Mein Profil',guest:'Deine Fahreridentität beginnt hier.',guestLead:'Verbinde dein Steam-Konto, um Ergebnisse zu sehen und dein ATXRACING-Profil zu gestalten.',login:'Mit Steam anmelden',welcome:'Willkommen',help:'Erste Schritte',helpText:'Vervollständige dein Profil in deinem Tempo. So können dich andere Fahrer besser kennenlernen.',identity:'Identität',photo:'Foto',team:'Team',bio:'Vorstellung',links:'Links',done:'Profil vollständig',edit:'Profil anpassen',displayName:'Fahrername',country:'Land (2-Buchstaben-Code)',number:'Startnummer',bioFr:'Vorstellung auf Französisch',bioEn:'Vorstellung auf Englisch',twitch:'Twitch',tiktok:'TikTok',youtube:'YouTube',website:'Website',save:'Profil speichern',saving:'Speichern…',saved:'Profil gespeichert.',error:'Profil konnte nicht gespeichert werden. Angaben prüfen.',avatar:'Foto wählen (JPG, PNG oder WebP, max. 2 MB)',upload:'Foto aktualisieren',uploading:'Foto wird hochgeladen…',logout:'Abmelden',results:'Rennergebnisse',empty:'Noch keine veröffentlichten Ergebnisse.',public:'Öffentliches Profil ansehen',rank:'Leistung',safe:'SAFE',races:'Rennen',wins:'Siege',podiums:'Podien',points:'Punkte',best:'Bestzeiten',noTime:'Noch keine veröffentlichte Runde.',first:'Deine erste Anmeldung ist abgeschlossen. Folge diesen Schritten für dein Fahrerprofil.',authError:'Steam-Anmeldung nicht abgeschlossen. Bitte erneut versuchen.'},
 it:{connect:'Accedi con Steam',my:'Il mio profilo',guest:'La tua identità da pilota inizia qui.',guestLead:'Collega Steam per vedere i risultati e personalizzare il profilo ATXRACING.',login:'Accedi con Steam',welcome:'Benvenuto',help:'Primi passi',helpText:'Completa il profilo con calma. Questi passaggi aiutano gli altri piloti a conoscerti.',identity:'Identità',photo:'Foto',team:'Squadra',bio:'Presentazione',links:'Link',done:'profilo completo',edit:'Personalizza il mio profilo',displayName:'Nome pilota',country:'Paese (codice di 2 lettere)',number:'Numero di gara',bioFr:'Presentazione in francese',bioEn:'Presentazione in inglese',twitch:'Twitch',tiktok:'TikTok',youtube:'YouTube',website:'Sito web',save:'Salva il profilo',saving:'Salvataggio…',saved:'Profilo salvato.',error:'Impossibile salvare. Controlla i dati.',avatar:'Scegli una foto (JPG, PNG o WebP, max 2 MB)',upload:'Aggiorna la foto',uploading:'Caricamento foto…',logout:'Esci',results:'Storico gare',empty:'Nessun risultato pubblicato.',public:'Vedi il mio profilo pubblico',rank:'Prestazione',safe:'SAFE',races:'Gare',wins:'Vittorie',podiums:'Podi',points:'Punti',best:'Giri migliori',noTime:'Nessun giro pubblicato.',first:'Il primo accesso è riuscito. Segui questi passaggi per presentare il tuo percorso.',authError:'Accesso Steam non completato. Riprova.'},
 es:{connect:'Iniciar sesión con Steam',my:'Mi perfil',guest:'Tu identidad como piloto empieza aquí.',guestLead:'Conecta Steam para ver resultados y personalizar tu perfil ATXRACING.',login:'Iniciar sesión con Steam',welcome:'Bienvenido',help:'Primeros pasos',helpText:'Completa tu perfil a tu ritmo. Estos pasos ayudan a otros pilotos a conocerte.',identity:'Identidad',photo:'Foto',team:'Equipo',bio:'Presentación',links:'Enlaces',done:'perfil completo',edit:'Personalizar mi perfil',displayName:'Nombre de piloto',country:'País (código de 2 letras)',number:'Número de coche',bioFr:'Presentación en francés',bioEn:'Presentación en inglés',twitch:'Twitch',tiktok:'TikTok',youtube:'YouTube',website:'Web',save:'Guardar perfil',saving:'Guardando…',saved:'Perfil guardado.',error:'No se pudo guardar. Revisa los datos.',avatar:'Elige una foto (JPG, PNG o WebP, máximo 2 MB)',upload:'Actualizar foto',uploading:'Subiendo foto…',logout:'Cerrar sesión',results:'Historial de carreras',empty:'Aún no hay resultados publicados.',public:'Ver mi perfil público',rank:'Rendimiento',safe:'SAFE',races:'Carreras',wins:'Victorias',podiums:'Podios',points:'Puntos',best:'Mejores vueltas',noTime:'Aún no hay vueltas publicadas.',first:'Tu primer acceso se completó. Sigue estos pasos para mostrar tu trayectoria.',authError:'El inicio de sesión con Steam no se completó. Inténtalo de nuevo.'}
 }[lang];
 const node=(tag,cls,txt)=>{const e=document.createElement(tag);if(cls)e.className=cls;if(txt!=null)e.textContent=String(txt);return e};
 const label=document.querySelector('[data-steam-label]'),header=document.querySelector('[data-steam-link]');
 if(label)label.textContent=ui.connect;
 const slug=id=>base+lang+'/'+game+'/profile.html'+(id?'?driver='+encodeURIComponent(id):'');
 const token=()=>sessionStorage.getItem(storageKey);
 const request=async(path,options={})=>{const response=await fetch(endpoint+path,options);const data=await response.json().catch(()=>({}));if(!response.ok)throw Error(data.error||response.status);return data};
 const initials=name=>String(name||'AT').slice(0,2).toUpperCase();
 const safeImage=url=>typeof url==='string'&&/^https:\/\//.test(url)?url:null;
 function photo(driver){const box=node('span','account-avatar',initials(driver.display_name));const url=safeImage(driver.avatar_url);if(url){const img=node('img');img.src=url;img.alt='';img.referrerPolicy='no-referrer';img.onerror=()=>img.remove();box.replaceChildren(img)}return box}
 function link(href,txt,cls='account-button'){const a=node('a',cls,txt);a.href=href;return a}
 function heading(driver){header.href=slug();header.classList.add('is-connected');header.replaceChildren(photo(driver),node('span','steam-account-name',driver.display_name||ui.my));header.setAttribute('aria-label',ui.my)}
 function guest(message){if(!profile)return;profile.replaceChildren();const card=node('div','account-guest');card.append(node('span','eyebrow','STEAM / ATXRACING'),node('h2','',ui.guest),node('p','',ui.guestLead));if(message)card.append(node('p','account-error',message));card.append(link(document.querySelector('[data-steam-link]').getAttribute('data-login-href')||document.querySelector('[data-steam-link]').href,ui.login));profile.append(card)}
 function completion(driver){return [[ui.identity,!!driver.display_name],[ui.photo,!!safeImage(driver.avatar_url)],[ui.team,!!driver.team_name],[ui.bio,!!(driver.bio_fr||driver.bio_en)],[ui.links,!!(driver.twitch_url||driver.tiktok_url||driver.youtube_url||driver.website_url)]]}
 function field(form,name,title,value,max=300){const label=node('label');label.append(node('span','',title));const large=name==='bioFr'||name==='bioEn';const input=node(large?'textarea':'input');input.name=name;input.maxLength=max;input.value=value||'';if(large)input.rows=3;else if(['twitchUrl','tiktokUrl','youtubeUrl','websiteUrl'].includes(name))input.type='url';label.append(input);form.append(label)}
 const lap=ms=>ms>0?`${Math.floor(ms/60000)}:${String(Math.floor(ms/1000)%60).padStart(2,'0')}.${String(ms%1000).padStart(3,'0')}`:'—';
 function owner(driver){if(!profile)return;profile.replaceChildren();const directory=document.querySelector('#public-directory'),results=document.querySelector('#results');if(directory)directory.hidden=true;if(results)results.hidden=true;
  const card=node('div','account-card'),hero=node('div','account-hero'),identity=node('div');identity.append(node('span','eyebrow',ui.welcome+' / ATXRACING'),node('h2','',driver.display_name||ui.my),node('p','',driver.team_name||'ATXRACING'));hero.append(photo(driver),identity);card.append(hero);
  const steps=completion(driver),complete=steps.filter(x=>x[1]).length,progress=node('div','account-progress');progress.append(node('strong','',Math.round(complete/steps.length*100)+'% '+ui.done));const rail=node('span','account-progress-bar'),fill=node('i');fill.style.width=complete/steps.length*100+'%';rail.append(fill);progress.append(rail);card.append(progress);
  const checklist=node('div','account-checklist');if(complete<steps.length){checklist.append(node('h3','',ui.help),node('p','',ui.helpText));if(!localStorage.getItem('atx-profile-seen-'+driver.id))checklist.append(node('p','first-use-tip',ui.first))}steps.forEach(([name,ok])=>checklist.append(node('span',ok?'complete':'incomplete',(ok?'✓ ':'○ ')+name)));if(complete<steps.length)card.append(checklist);
  const stats=node('div','account-stats');[[ui.races,driver.stats?.races],[ui.wins,driver.stats?.wins],[ui.podiums,driver.stats?.podiums],[ui.points,driver.stats?.points]].forEach(([name,num])=>{const stat=node('div');stat.append(node('b','',num??0),node('small','',name));stats.append(stat)});card.append(stats);
  const overall=driver.ratings?.find(r=>r.circuit_key==='overall');if(overall){const badges=node('div','account-badges');badges.append(node('span','',ui.rank+' · '+(overall.performance_class||'—').toUpperCase()+(overall.performance_score!=null?' · '+Number(overall.performance_score).toFixed(2)+'%':'')),node('span','',ui.safe+' · '+(overall.safety_class||'—').toUpperCase()+(overall.safety_score!=null?' · '+Math.round(overall.safety_score)+'/100':'')));card.append(badges)}
  const actions=node('div','account-actions');actions.append(link(slug(driver.id),ui.public,'pill'));const logout=node('button','pill',ui.logout);logout.type='button';logout.onclick=async()=>{try{await request('auth-logout',{method:'POST',headers:{Authorization:'Bearer '+token()}})}catch{}sessionStorage.removeItem(storageKey);location.href=slug()};actions.append(logout);card.append(actions);profile.append(card);
  const editor=node('section','account-editor');editor.append(node('span','eyebrow','STEAM / '+game.toUpperCase()),node('h2','',ui.edit));const form=node('form','account-form');field(form,'displayName',ui.displayName,driver.display_name,64);field(form,'teamName',ui.team,driver.team_name,64);field(form,'countryCode',ui.country,driver.country_code,2);field(form,'carNumber',ui.number,driver.car_number,4);field(form,'bioFr',ui.bioFr,driver.bio_fr,500);field(form,'bioEn',ui.bioEn,driver.bio_en,500);field(form,'twitchUrl',ui.twitch,driver.twitch_url);field(form,'tiktokUrl',ui.tiktok,driver.tiktok_url);field(form,'youtubeUrl',ui.youtube,driver.youtube_url);field(form,'websiteUrl',ui.website,driver.website_url);
  const status=node('p','form-status');status.setAttribute('role','status');const save=node('button','action',ui.save);save.type='submit';form.append(status,save);form.onsubmit=async ev=>{ev.preventDefault();save.disabled=true;status.textContent=ui.saving;try{const values=Object.fromEntries(new FormData(form).entries());await request('manage-profile',{method:'POST',headers:{Authorization:'Bearer '+token(),'Content-Type':'application/json'},body:JSON.stringify(values)});const fresh=await request('auth-session',{headers:{Authorization:'Bearer '+token()}});localStorage.setItem('atx-profile-seen-'+driver.id,'1');owner(fresh.driver);heading(fresh.driver);profile.querySelector('.form-status').textContent=ui.saved}catch{status.textContent=ui.error}finally{save.disabled=false}};editor.append(form);
  const upload=node('div','account-upload'),fileLabel=node('label','',ui.avatar),file=node('input');file.type='file';file.accept='image/jpeg,image/png,image/webp';fileLabel.append(file);const uploadButton=node('button','pill',ui.upload);uploadButton.type='button';const uploadStatus=node('span');uploadButton.onclick=async()=>{const image=file.files?.[0];if(!image||image.size>2*1024*1024||!['image/jpeg','image/png','image/webp'].includes(image.type)){uploadStatus.textContent=ui.error;return}uploadButton.disabled=true;uploadStatus.textContent=ui.uploading;try{const data=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=reject;reader.readAsDataURL(image)});await request('upload-driver-avatar',{method:'POST',headers:{Authorization:'Bearer '+token(),'Content-Type':'application/json'},body:JSON.stringify({image:data})});const fresh=await request('auth-session',{headers:{Authorization:'Bearer '+token()}});owner(fresh.driver);heading(fresh.driver)}catch{uploadStatus.textContent=ui.error}finally{uploadButton.disabled=false}};upload.append(fileLabel,uploadButton,uploadStatus);editor.append(upload);profile.append(editor);
  const history=node('section','account-history');history.append(node('h2','',ui.results));const published=driver.results||[];if(!published.length)history.append(node('p','empty',ui.empty));else{const list=node('div','account-result-list');published.slice(0,30).forEach(r=>{const event=Array.isArray(r.event)?r.event[0]:r.event||{};const row=node('div');row.append(node('strong','',event['title_'+lang]||event.title_en||event.title_fr||event.circuit_name||'—'),node('span','',r.car_model_name||'—'),node('b','',lap(r.best_lap_ms)));list.append(row)});history.append(list)}profile.append(history);
  if(driver.id)fetch(endpoint+'public-driver-sectors').then(r=>r.ok?r.json():null).then(data=>{const laps=(data?.sectors||[]).filter(x=>x.driver_id===driver.id&&x.best_lap_ms>0);if(!laps.length)return;const box=node('section','account-history');box.append(node('h2','',ui.best));const list=node('div','account-result-list');laps.forEach(c=>{const row=node('div');row.append(node('strong','',c.circuit_name),node('span','',c.best_lap_session_type||'—'),node('b','',lap(c.best_lap_ms)));list.append(row)});box.append(list);profile.append(box)}).catch(()=>{});
 }
 async function boot(){const current=header?.href;if(header)header.dataset.loginHref=current||'';
  const fragment=new URLSearchParams(location.hash.slice(1)),code=fragment.get('steam_code'),error=fragment.get('steam')==='error';if(code){history.replaceState(null,'',location.pathname+location.search);try{const data=await request('auth-session',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({code})});sessionStorage.setItem(storageKey,data.access_token)}catch{if(profile)guest(ui.authError)}}
  const sessionToken=token();if(sessionToken){try{const data=await request('auth-session',{headers:{Authorization:'Bearer '+sessionToken}});heading(data.driver);if(profile&&!new URLSearchParams(location.search).has('driver'))owner(data.driver);return}catch{sessionStorage.removeItem(storageKey)}}
  if(profile&&!new URLSearchParams(location.search).has('driver'))guest(error?ui.authError:null);
 }
 boot();
})();
